async function api<T>(path: string, init: RequestInit = {}): Promise<T> {
  const response = await fetch(`/api${path}`, { ...init, credentials: 'same-origin', headers: { ...(init.body ? { 'Content-Type': 'application/json' } : {}), ...init.headers } })
  if (!response.ok) { let message = `Request failed (${response.status})`; try { const body = await response.json() as { detail?: unknown }; if (typeof body.detail === 'string') message = body.detail; else if (Array.isArray(body.detail)) message = body.detail.map((x) => typeof x === 'object' && x && 'msg' in x ? String((x as {msg: unknown}).msg) : String(x)).join('. ') } catch { /* no response body */ }; const e = new Error(message) as Error & {status:number}; e.status = response.status; throw e }
  return response.json() as Promise<T>
}
const statusOf = (e: unknown) => typeof e === 'object' && e && 'status' in e ? Number((e as {status:number}).status) : 0
