function fitWithOverlayPadding(map:L.Map,bounds:L.LatLngBounds,panelOpen:boolean,smallScreen:boolean){
 map.invalidateSize({pan:false})
 const size=map.getSize(),panel=panelOpen?document.querySelector('.floating-panel')?.getBoundingClientRect():null
 const left=smallScreen?24:panel?panel.right+24:24
 const top=smallScreen&&panel?Math.min(panel.bottom+20,size.y-190):80
 map.fitBounds(bounds,{maxZoom:17,paddingTopLeft:[left,Math.max(80,top)],paddingBottomRight:[24,smallScreen?160:110]})
}
