 async function previewAddress(p:SearchParcel){const seq=++previewSeq.current;setBusyArea(p.id);setDraftError('');setPreviewWarnings([]);setPreviewChoice(null);setPreview([]);setResolvedPreview(null);setPreviewAnchor(p.latitude!==null&&p.longitude!==null?[p.latitude,p.longitude]:null);setPreviewError('');try{const a=await api<Area>('/areas/resolve',{method:'POST',body:JSON.stringify({kind:'address',parcel_id:p.id})});if(seq!==previewSeq.current)return;setInspectionArea(a);setSelectedAreaId(a.id);setSelectedParcelId(p.id);setHouseSheetOpen(true);setResolvedPreview(a);setPreview([]);setPreviewAnchor(centerOf(a.geometry)??(p.latitude!==null&&p.longitude!==null?[p.latitude,p.longitude]:null));setPreviewFitStamp(v=>v+1)}catch(e){if(seq===previewSeq.current){setDraftError(errorText(e));if(statusOf(e)===401)setAuthenticated(false)}}finally{if(seq===previewSeq.current)setBusyArea('')}}
 function addPreview(){const c=previewChoice||preview[0];if(preview.length>1&&!previewChoice)return;if(c)void resolve({kind:'subdivision',mcr_key:c.mcr_key});else if(resolvedPreview){invalidate();const a=resolvedPreview;setAreas(curr=>curr.some(x=>x.id===a.id)?curr:[...curr,a]);setPreview([]);setPreviewChoice(null);setPreviewWarnings([]);setPreviewError('');setResolvedPreview(null);setPreviewAnchor(null);setSelectedAreaId('');setSelectedParcelId('');setInspectionArea(null);setHouseSheetOpen(true);if(a.parcels[0])setOriginalAddress(a.parcels[0].address)}}
 function toggleSample(id:string,areaId:string){if(mode!=='sample'||areaId!==selectedAreaId||excluded.includes(id))return;setSamples(current=>current.includes(id)?current.filter(sample=>sample!==id):[...current,id])}
 function startSampleMode(){const area=areas.find(item=>item.id===selectedAreaId);if(!area){setNotice('Open a neighborhood before selecting samples.');return;}setSampleSnapshot({intent,samples:[...samples]});setMode('sample');setSelectedParcelId('');setHouseSheetOpen(false)}
