 function finishDraw(cancel=false){if(cancel){setVertices([]);setEditingArea(null);setBusyArea('');setMode('browse');setHouseSheetOpen(Boolean(selectedAreaId));return}if(vertices.length<3||lockedConfirmed||busyArea)return;const geometry={type:'Polygon',coordinates:[[...vertices,vertices[0]].map(([lat,lng])=>[lng,lat])]} as Geometry;void resolve({kind:'polygon',geometry,label:drawLabel.trim()||'Custom area',...(editingArea?{original_area_id:editingArea.id}:{})})}
