 function reviewOneHouse(id:string){const area=areas.find(item=>item.id===selectedAreaId)||inspectionArea;const scope=area?selectionForArea(area):activeSelection;const ids=area?.parcels.map(parcel=>parcel.id)||groupParcels.map(parcel=>parcel.id);setReviewSelection({...scope,excluded_ids:[...new Set([...scope.excluded_ids.filter(parcelId=>parcelId!==id),...ids.filter(parcelId=>parcelId!==id)])],sample_ids:[id],intent:'single'});setHouseSheetOpen(false);setFiltersOpen(true)}
 async function saveSelection(){if(!canSave)return;const rev=draftRevision.current,body=JSON.stringify({name:name.trim(),...(originalAddress.trim()?{original_address:originalAddress.trim()}:{}),selection:activeSelection});setRunBusy(true);setRunError('');const key=saveKey.current?.body===body?saveKey.current.key:crypto.randomUUID();saveKey.current={body,key};try{const r=await api<NewRun>('/runs',{method:'POST',headers:{'Idempotency-Key':key},body});if(rev===draftRevision.current){setSavedRun(r);setAreas(r.areas);setExcluded(r.excluded_ids);setSamples(r.sample_ids);setIntent(r.intent);setReview(r.review||null);setNotice('Selection snapshot saved. Later edits create a new draft.');window.history.replaceState({},'',`/runs/${encodeURIComponent(r.id)}`)}await loadRecent()}catch(e){if(rev===draftRevision.current)setRunError(errorText(e));if(statusOf(e)===401)setAuthenticated(false)}finally{setRunBusy(false)}}
 const selectionKey=useMemo(()=>JSON.stringify({selection:activeSelection,ahj_overrides:ahjOverrides}),[areas,excluded,intent,samples,includedIds,ahjOverrides])
 useEffect(()=>{const seq=++reviewSeq.current;if(!authenticated||!areas.length||!includedIds.length||savedRun?.status==='confirmed'){setReviewBusy(false);return;}setReviewBusy(true);setReviewError('');const timer=setTimeout(()=>{api<Review>('/neighborhoods/review',{method:'POST',body:JSON.stringify({selection:activeSelection,ahj_overrides:ahjOverrides})}).then(r=>{if(seq===reviewSeq.current)setReview(r)}).catch(e=>{if(seq===reviewSeq.current){setReviewError(errorText(e));if(statusOf(e)===401)setAuthenticated(false)}}).finally(()=>{if(seq===reviewSeq.current)setReviewBusy(false)})},350);return()=>{clearTimeout(timer);if(seq===reviewSeq.current)reviewSeq.current++}},[authenticated,selectionKey,savedRun?.status])
