 if(checking)return <main className="screen-center"><div className="spinner" aria-label="Checking staff session"/></main>
 if(!authenticated)return <main className="login-page"><div className="login-card"><Brand/><p className="eyebrow">STAFF WORKSPACE</p><h1>Sign in to continue</h1><p className="muted">Use your staff access token to open the local solar design workspace.</p><form onSubmit={signIn} className="stack"><label htmlFor="staff-token">Staff access token</label><input id="staff-token" type="password" autoComplete="current-password" value={token} onChange={e=>setToken(e.target.value)} required/><button className="primary" disabled={loginBusy||!token}>{loginBusy?'Signing in…':'Sign in'}</button>{authError&&<p role="alert" className="error-box">{authError}</p>}</form><p className="login-foot">Your token is sent to the server for session creation. It is not stored in this app.</p></div></main>
