            {searchBusy&&<p className="inline-status"><span className="mini-spinner"/> Searching…</p>}{searchError&&<p className="inline-alert" role="alert">{searchError}</p>}{draftError&&<p className="inline-alert" role="alert">{draftError}</p>}{previewError&&<p className="inline-alert" role="status">{previewError}</p>}{previewWarnings.length>0&&<div className="lookup-notes"><b>Lookup notes</b>{previewWarnings.map((w,i)=><span key={`${i}-${w}`}>{w}</span>)}</div>}{busyArea&&<p className="inline-status"><span className="mini-spinner"/> {busyArea==='lookup'?'Finding a neighborhood…':'Loading boundary and homes…'}</p>}
      

